    async function render(preferredTaskFilter) {
      const match = location.pathname.match(/^\/projects\/([^/]+)$/);
      if (match) {
        const projects = await fetch('/api/projects').then(response => response.json());
        const project = projects.find(item => item.id === decodeURIComponent(match[1]));
        if (!project) { app.innerHTML = '<p>Project not found.</p><button class="back" type="button">Projects</button>'; }
        else {
          const tasks = await fetch(`/api/projects/${encodeURIComponent(project.id)}/tasks`).then(response => response.json());
          app.innerHTML = `<button class="back" type="button">Projects</button><section class="project-detail"><h2>${escapeHtml(project.name)}</h2><form id="task-form"><label for="task-title">Task title</label><input id="task-title" type="text" autocomplete="off"><button type="submit">Create task</button></form><p id="task-error" role="alert" hidden></p><label for="task-filter">Task filter</label><select id="task-filter" aria-label="Task filter"><option${preferredTaskFilter === 'All' || !preferredTaskFilter ? ' selected' : ''}>All</option><option${preferredTaskFilter === 'Open' ? ' selected' : ''}>Open</option><option${preferredTaskFilter === 'Completed' ? ' selected' : ''}>Completed</option></select><div id="tasks">${tasks.map(task => `<div class="task-row" data-testid="task-row" data-completed="${task.completed}"><input type="checkbox" aria-label="Complete ${escapeHtml(task.title)}" data-task-id="${escapeHtml(task.id)}" ${task.completed ? 'checked' : ''}><span>${escapeHtml(task.title)}</span></div>`).join('')}</div></section>`;
          const applyFilter = () => { const filter = app.querySelector('#task-filter').value; app.querySelectorAll('.task-row').forEach(row => { row.hidden = filter === 'Open' ? row.dataset.completed === 'true' : filter === 'Completed' ? row.dataset.completed !== 'true' : false; }); };
          app.querySelector('#task-filter').addEventListener('change', applyFilter);
          applyFilter();
          app.querySelectorAll('[data-task-id]').forEach(box => box.addEventListener('change', async () => { const filter = app.querySelector('#task-filter').value; await fetch(`/api/tasks/${encodeURIComponent(box.dataset.taskId)}`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ completed: box.checked }) }); render(filter); }));
          app.querySelector('#task-form').addEventListener('submit', async event => { event.preventDefault(); const error = app.querySelector('#task-error'); const response = await fetch(`/api/projects/${encodeURIComponent(project.id)}/tasks`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ title: app.querySelector('#task-title').value }) }); if (!response.ok) { error.textContent = 'Task title is required'; error.hidden = false; return; } render(); });
        }
        app.querySelector('.back').addEventListener('click', () => { history.pushState({}, '', '/'); render(); });
        return;
      }
      const projects = await fetch('/api/projects').then(response => response.json());
      app.innerHTML = `<form id="create-form"><label for="project-name">Project name</label><input id="project-name" name="name" type="text" autocomplete="off"><button type="submit">Create project</button></form><p id="error" role="alert" hidden></p><section id="projects" aria-label="Projects">${projects.map(project => `<div class="project-row" data-testid="project-row"><span class="project-name">${escapeHtml(project.name)}</span><button type="button" data-project-id="${escapeHtml(project.id)}">Open project</button></div>`).join('')}</section>`;
      app.querySelector('#create-form').addEventListener('submit', async event => {
        event.preventDefault();
        const input = app.querySelector('#project-name');
        const error = app.querySelector('#error');
        const response = await fetch('/api/projects', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ name: input.value }) });
        if (!response.ok) { error.textContent = 'Project name is required'; error.hidden = false; return; }
